    /**
     * Tests getting all OrderLines.
     *
     * @return    Collection
     */
    public List<OrderLine> testGetAll() throws Throwable {
    LOGGER.info( "OrderLineTest:testGetAll() - Retrieving Collection of OrderLines:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all OrderLine : " );
    List<OrderLine> collection  = null;

    try {
        // call the static get method on the OrderLineService
        collection = service.getAllOrderLine();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            OrderLine currEntity  = null;
            Iterator<OrderLine> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getOrderLineId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

